SELECT CASE WHEN sqft >= 17753 THEN 'LARGE' ELSE 'SMALL' END AS sqft_tier, DATE_TRUNC('YEAR', opened_date) AS year_start, city, STDDEV_SAMP(sqft) AS sqft_stddev, BIT_OR(sqft) AS sqft_bit_or, SUM(CASE WHEN city = 'New York' THEN sqft ELSE 0 END) AS new_york_sqft, BIT_AND(sqft) AS sqft_bit_and, SUM(CASE WHEN region = 'South' THEN sqft ELSE 0 END) AS south_sqft FROM stores GROUP BY CUBE (CASE WHEN sqft >= 17753 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('YEAR', opened_date), city) ORDER BY sqft_bit_or NULLS LAST
